using System.Security.Claims;
using HrSystemDhg.Web.Data;
using HrSystemDhg.Web.Models;
using HrSystemDhg.Web.Pages.Admin;
using HrSystemDhg.Web.Pages.Hr;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
var cs=Environment.GetEnvironmentVariable("SHARED_TEST_CONNECTION")!;
if (!cs.Contains("127.0.0.1") || !cs.Contains("Database=shared_fixture")) throw new Exception("Local disposable database required");
var options=new DbContextOptionsBuilder<HrDbContext>().UseMySql(cs,new MySqlServerVersion(new Version(8,0,0))).Options;
await using var db=new HrDbContext(options);
await db.Database.MigrateAsync();
var branches=new[]{new Branch{Name="Office A",Code="A"},new Branch{Name="Office B",Code="B"},new Branch{Name="Unrelated office",Code="C"}};
db.Branchs.AddRange(branches); await db.SaveChangesAsync();
var http=new DefaultHttpContext {User=new ClaimsPrincipal(new ClaimsIdentity(new[]{new Claim(ClaimTypes.Name,"fixture"),new Claim(ClaimTypes.Role,"Admin")},"fixture"))};
OrgEditModel Form(int id=0)=>new(db){Kind="Department",Id=id,Name="Admin and Finance",Code="AF",ParentId=branches[0].Id,AdditionalBranchIds=[branches[1].Id],PageContext=new PageContext{HttpContext=http},TempData=new TempDataDictionary(http,new MemoryTemp())};
var create=Form(); if(await create.OnPostAsync() is not RedirectToPageResult) throw new Exception("Shared department save failed");
db.ChangeTracker.Clear();var department=await db.Departments.SingleAsync();
if (!department.ServesBranch(branches[0].Id)||!department.ServesBranch(branches[1].Id)||department.ServesBranch(branches[2].Id))throw new Exception("Membership failure");
var lookup=new RegisterModel(db); // lookup has no external service dependencies
var optionsResult=(JsonResult)await lookup.OnGetDepartmentsAsync(branches[1].Id);
if(!System.Text.Json.JsonSerializer.Serialize(optionsResult.Value).Contains("Admin and Finance"))throw new Exception("Secondary branch registration lookup failed");
var employee=new Employee{EmployeeNumber="EMP0001",FullName="Fixture Employee",WorkEmail="fixture@example.test",HireDate=new DateTime(2026,1,1)};
db.Employees.Add(employee);await db.SaveChangesAsync();
var details=new DetailsModel(db){PageContext=new PageContext{HttpContext=http}};
if(await details.OnPostTransferAsync(employee.Id,branches[1].Id,department.Id,null,"Officer",new DateTime(2026,2,1)) is not RedirectToPageResult)throw new Exception("Secondary branch assignment failed");
if((await db.EmployeeAssignments.SingleAsync()).BranchId!=branches[1].Id)throw new Exception("Assignment incorrectly used primary branch");
if(await details.OnPostTransferAsync(employee.Id,branches[2].Id,department.Id,null,"Officer",new DateTime(2026,3,1)) is not BadRequestResult)throw new Exception("Unlinked branch accepted");
var remove=Form(department.Id);remove.AdditionalBranchIds=[];
if(await remove.OnPostAsync() is not PageResult || remove.ModelState.IsValid)throw new Exception("Historical branch removal accepted");
var duplicate=Form();duplicate.ParentId=branches[1].Id;duplicate.AdditionalBranchIds=[];
if(await duplicate.OnPostAsync() is not PageResult || duplicate.ModelState.IsValid)throw new Exception("Overlapping department code accepted");
db.Users.Add(new ApplicationUser{Id="scoped",UserName="scoped"});db.UserBranchScopes.Add(new(){UserId="scoped",BranchId=branches[1].Id});await db.SaveChangesAsync();
var scopedHttp=new HttpContextAccessor{HttpContext=new DefaultHttpContext{User=new ClaimsPrincipal(new ClaimsIdentity(new[]{new Claim(ClaimTypes.NameIdentifier,"scoped"),new Claim(ClaimTypes.Role,"HR")},"fixture"))}};
await using var scoped=new HrDbContext(options,scopedHttp);
if(!await scoped.Departments.AnyAsync(x=>x.Id==department.Id)||await scoped.Branchs.AnyAsync(x=>x.Id==branches[0].Id)||!await scoped.EmployeeAssignments.AnyAsync(x=>x.EmployeeId==employee.Id))throw new Exception("Secondary branch scope failure");
Console.WriteLine("PASS: shared department CRUD, registration lookup, assignment branch, invalid combinations, history protection, duplicate code and branch scope.");
class MemoryTemp:ITempDataProvider{public IDictionary<string,object> LoadTempData(HttpContext c)=>new Dictionary<string,object>(); public void SaveTempData(HttpContext c,IDictionary<string,object> v){}}
